Lemma read_ok : forall Y v w fd buf cnt, 0 <= cnt < 2^64 ->
  TSM (JX Y v w) (msys (NRead fd buf cnt) (dec_read buf cnt))
      (fun a RNG A s mo => JX Y v w RNG A s mo /\ match a with RdData bs => zlength bs <= cnt | RdErr _ => True end).
Proof.
  intros Y v w fd buf cnt Hcnt. apply TSM_msys_io; [exact I| apply JX_acct|].
  intros RNG A s mo rsp mo' evs x HJ Hst Hdec. split; [eapply (JX_io (NRead fd buf cnt)); eauto; exact I|].
  destruct (dec_read_Some buf cnt rsp x ltac:(lia) Hdec) as [ci Hx]. destruct x as [e|bs]; [exact I|].
  unfold zlength. lia.
Qed.

Lemma exit_node_ok : forall Y v w c (Q : postM Empty_set), TSM (JX Y v w) (msys (NExit c) dec_exit) Q.
Proof.
  intros Y v w c Q RNG A s mo HJ. unfold msys, enode.
  apply TS_io; [exact I| eapply JX_acct; exact HJ|].
  intros rsp mo' evs Hst _. cbn [nstep] in Hst. destruct Hst.
Qed.

