Lemma run_calls_ok : forall X n payload rcd v w, (length X <= 2)%nat -> zlength payload <= MAX_INPUT ->
  Z.of_nat n * FUZZ_COST <= v -> Z.of_nat n * FUZZ_OPS <= w ->
