(* [comment removed for export] *)
(* [comment removed for export] *)
(* [comment removed for export] *)
Section Driver.
Variable io_ : IOStyle St.
Variables (malloc : Z -> M St (option P)) (free : P -> M St unit) (read_stage : Z).   (* [comment removed for export] *)
Variables (alloc_init : Z -> M St unit) (run : Z -> list Z -> M St Z) (alloc_count : M St Z).

Hypothesis Um : forall Y v w n, 0 <= n <= REQMAX -> HISTOK (n :: sizes Y) ->
  TSM (fun RNG A s mo => JX Y v w RNG A s mo /\ n <= v /\ 1 <= w) (malloc n)
      (fun r RNG A s mo => exists q, r = Some q /\ JX ((q, n) :: Y) (v - n) (w - 1) RNG A s mo /\ n < 2^63).
Hypothesis Uf : forall Y v w p n, TSM (JX ((p, n) :: Y) v w) (free p) (fun _ => JX Y v w).
Hypothesis Udiag : forall Y v w d, TSJ Y v w (io_diag io_ d).
Hypothesis Uinit : forall Y v w bm, TSJ Y v w (alloc_init bm).
Hypothesis Ucount : forall Y v w, TSJ Y v w alloc_count.
Hypothesis Urun : forall X cfg payload v w, (length X <= 1)%nat -> zlength payload <= MAX_INPUT -> RUN_COST <= v -> RUN_OPS <= w ->
  TSM (JX X v w) (run cfg payload) (fun _ => JX X (v - RUN_COST) (w - RUN_OPS)).
Hypothesis Uioexit : forall Y v w, TSJ Y v w (io_exit io_).

(* [comment removed for export] *)
Definition rd_pot (cap : Z) : Z := 2^27 - 2 * cap.
Definition READ_COST : Z := 2^27.
Definition MAIN_COST : Z := READ_COST + RUN_COST.

(* [comment removed for export] *)
Definition rd_rel (vb wb : Z) (st : @rd_st P) : preT := fun RNG A s mo =>
  exists v w, JX [(rd_buf st, rd_cap st)] v w RNG A s mo /\ zlength (rd_content st) <= rd_cap st
            /\ (exists k, (k <= 10)%nat /\ rd_cap st = 65536 * 2 ^ Z.of_nat k /\ wb + (10 - Z.of_nat k) <= w) /\ vb + rd_pot (rd_cap st) <= v /\ 0 <= wb.

Definition QR (vb wb : Z) (r : @rd_result P) : preT :=
  match r with
  | RdExit => fun RNG A s mo => exists X' v' w', JX X' v' w' RNG A s mo
  | RdDone b c => fun RNG A s mo => (exists cap, JX [(b, cap)] vb wb RNG A s mo) /\ zlength c <= MAX_INPUT
  end.

Lemma read_loop_body_ok : forall fd path vb wb st, 0 <= vb ->
  TSM (rd_rel vb wb st) (read_loop_body io_ malloc free read_stage fd path st)
      (fun r => match r with inl st' => rd_rel vb wb st' | inr res => QR vb wb res end).
Proof.
